// Vulnerable: email = "' OR '1'='1' --" devuelve todos los usuarios
const r1 = await pool.query(
  `SELECT * FROM usuarios WHERE email = '${email}'`);

// Seguro: el valor viaja como parámetro $1
const r2 = await pool.query(
  'SELECT * FROM usuarios WHERE email = $1', [email]);

// DOM XSS: innerHTML interpreta el HTML de la reseña
tarjeta.innerHTML = `<p>${resena.texto}</p>`;       // vulnerable
// textContent lo trata siempre como texto
parrafo.textContent = resena.texto;                  // seguro

// Express: la CSP solo permite scripts del propio origen
app.use((req, res, next) => {
  res.set('Content-Security-Policy',
    "default-src 'self'; script-src 'self'; object-src 'none'");
  next();
});

res.cookie('sesion', id, {
  httpOnly: true,     // JavaScript no puede leerla
  secure: true,       // solo por HTTPS
  sameSite: 'lax',    // no viaja en POST desde otros sitios
  maxAge: 2 * 60 * 60 * 1000,
});

app.use(cors({
  origin: ['https://qatu.com'],   // lista explícita, nunca '*'
  credentials: true,
}));
